-- =====================================================================
-- Catálogo de misconceptions — unidad NUM-POT
-- Generado por cargar_misconceptions.py desde NUM-POT.yaml
-- NO EDITAR A MANO. Se edita el YAML y se vuelve a generar.
-- La transaccion la pone quien ejecuta:
--   psql -X -v ON_ERROR_STOP=1 -1 -f este_archivo.sql "$DATABASE_URL"
-- Este archivo NO trae begin/commit a proposito: anidarlos rompe
-- la atomicidad del -1.
-- =====================================================================

insert into misconceptions (code, name, description, example, area_id, node_id, origin)
select v.code, v.name, v.description, v.example, a.id, n.id,
       v.origin::misconception_origin
from (values
  ($c$POT-CONC-FACTOR$c$, $c$Cuenta un factor de más$c$, $c$Escribe a^n con n+1 factores. Nace de la frase "multiplicar la base por sí misma n veces", que leída literal da un factor extra. El concepto está bien; el conteo no.$c$, $c$2^3 = 2·2·2·2 = 16$c$, $c$NUM$c$, $c$NUM-POT-CONC$c$, $c$hipotesis$c$),
  ($c$POT-CONC-INV$c$, $c$Intercambia base y exponente$c$, $c$Resuelve a^n como n^a. No distingue quién se repite de cuántas veces se repite. Es invisible cuando base y exponente son iguales, y en 2^4 = 4^2 coincide por casualidad.$c$, $c$2^3 = 3^2 = 9$c$, $c$NUM$c$, $c$NUM-POT-CONC$c$, $c$hipotesis$c$),
  ($c$POT-CONC-MULT$c$, $c$Multiplica la base por el exponente$c$, $c$Resuelve a^n como a·n. Es el error raíz de toda la unidad: si la potencia se lee como una multiplicación, ninguna regla posterior tiene sentido. Se esconde en a^2, donde a·2 y a² a veces coinciden cerca, y en 2^2, donde coinciden exacto.$c$, $c$2^3 = 6$c$, $c$NUM$c$, $c$NUM-POT-CONC$c$, $c$hipotesis$c$),
  ($c$POT-CONC-SUMA$c$, $c$Suma la base y el exponente$c$, $c$Resuelve a^n como a+n. Menos frecuente que POT-CONC-MULT pero del mismo tipo: la potencia se lee como una operación entre dos números en vez de como un conteo de factores.$c$, $c$2^3 = 5$c$, $c$NUM$c$, $c$NUM-POT-CONC$c$, $c$hipotesis$c$),
  ($c$POT-SIG-EXP$c$, $c$Confunde base negativa con exponente negativo$c$, $c$Lee (-a)^n como a^(-n) y responde una fracción. El signo cambia de lugar en la lectura. Cruza con NUM-POT-NEG, que el estudiante todavía no vio.$c$, $c$(-2)^3 = 1/8$c$, $c$NUM$c$, $c$NUM-POT-SIG$c$, $c$hipotesis$c$),
  ($c$POT-SIG-NEG$c$, $c$Toda potencia de base negativa es negativa$c$, $c$Arrastra el signo de la base al resultado sin mirar el exponente. Error espejo de POT-SIG-POS, y como aquel, solo se delata en la mitad de los casos: con exponente impar acierta sin entender.$c$, $c$(-3)^2 = -9$c$, $c$NUM$c$, $c$NUM-POT-SIG$c$, $c$hipotesis$c$),
  ($c$POT-SIG-PAREN$c$, $c$No distingue -a^n de (-a)^n$c$, $c$Trata el signo como parte de la base aunque no haya paréntesis. Es el caso general de POT-CERO-SIGNO, que quedó registrado aparte porque el exponente cero se remedia por otro camino. Si al revisar datos las dos se disparan juntas, hay que fusionarlas.$c$, $c$-2^4 = 16$c$, $c$NUM$c$, $c$NUM-POT-SIG$c$, $c$hipotesis$c$),
  ($c$POT-SIG-POS$c$, $c$Toda potencia de base negativa es positiva$c$, $c$Sobregeneraliza "menos por menos es más" a cualquier exponente. Solo se hace visible con exponente impar: con exponente par la respuesta es correcta por la razón equivocada.$c$, $c$(-2)^3 = 8$c$, $c$NUM$c$, $c$NUM-POT-SIG$c$, $c$hipotesis$c$),
  ($c$POT-BASE-DIST$c$, $c$Aplica la regla con bases distintas$c$, $c$Usa a^m · b^n = (ab)^(m+n). No reconoce que la regla exige base común. Hace fallar los ítems de varios factores, donde hay que agrupar por base antes de operar.$c$, $c$2^3 · 3^2 = 6^5$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-BASE-OPERA$c$, $c$Opera también las bases$c$, $c$Multiplica o divide las bases además de operar los exponentes. La base no es un factor: es la identidad de la potencia. Cruza producto y cociente, y reaparece en NUM-POT-DIST.$c$, $c$2^3 · 2^2 = 4^5$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-COC-DIV$c$, $c$Divide los exponentes en el cociente$c$, $c$Aplica a^m : a^n = a^(m:n). Traslada la operación de las bases a los exponentes. Es el error más caro porque produce la respuesta correcta cuando m es múltiplo de n y el resultado coincide por azar.$c$, $c$5^6 : 5^2 = 5^3$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-COC-ORDEN$c$, $c$Resta los exponentes al revés$c$, $c$Aplica a^m : a^n = a^(n-m). Conoce la regla pero no el orden. Solo se hace visible cuando el exponente del denominador es mayor, porque con m > n el signo no delata nada.$c$, $c$3^2 : 3^5 = 3^3$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-COC-SUMA$c$, $c$Suma los exponentes en el cociente$c$, $c$Aplica a^m : a^n = a^(m+n). Es el error espejo de POT-PROD-RESTA. Se registran separados a propósito: ocurren en operaciones distintas y un estudiante puede tener uno sin el otro.$c$, $c$5^6 : 5^2 = 5^8$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-EXP-UNO$c$, $c$No reconoce que a es a^1$c$, $c$Trata el factor sin exponente visible como si no participara de la regla. Es un punto ciego de notación, no de concepto.$c$, $c$6^4 : 6 = 6^4$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-PROD-MULT$c$, $c$Multiplica los exponentes en el producto$c$, $c$Aplica a^m · a^n = a^(m·n). Usa la regla de potencia de una potencia donde va la del producto. Es la mitad de un par de reglas invertidas: quien comete este error suele cometer también POT-POT-SUMA.$c$, $c$2^3 · 2^2 = 2^6$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-PROD-RESTA$c$, $c$Resta los exponentes en el producto$c$, $c$Aplica a^m · a^n = a^(m-n). Usa la regla del cociente en el producto. Aparece cuando las dos reglas se enseñaron juntas y solo queda el recuerdo de que "algo se hace con los exponentes".$c$, $c$2^3 · 2^2 = 2^1$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-SUMA-PROD$c$, $c$Trata la suma de potencias como si fuera producto$c$, $c$Aplica la regla del producto a a^m + a^n. Confunde la operación entre potencias con la operación entre exponentes.$c$, $c$2^3 + 2^2 = 2^5$c$, $c$NUM$c$, $c$NUM-POT-PROD$c$, $c$hipotesis$c$),
  ($c$POT-POT-BASE$c$, $c$Opera la base con el exponente externo$c$, $c$Multiplica la base por el exponente de afuera en vez de aplicar la regla a los exponentes. Variante de POT-BASE-OPERA dentro del paréntesis.$c$, $c$(3^2)^4 = 6^8$c$, $c$NUM$c$, $c$NUM-POT-POT$c$, $c$hipotesis$c$),
  ($c$POT-POT-SUMA$c$, $c$Suma los exponentes en potencia de una potencia$c$, $c$Aplica (a^m)^n = a^(m+n). Es el espejo exacto de POT-PROD-MULT. Quien tiene los dos no tiene dos errores: tiene un solo par de reglas cambiado de lugar, y hay que decírselo así.$c$, $c$(2^3)^2 = 2^5$c$, $c$NUM$c$, $c$NUM-POT-POT$c$, $c$hipotesis$c$),
  ($c$POT-POT-TORRE$c$, $c$Lee la expresión como torre de potencias$c$, $c$Interpreta (a^m)^n como a^(m^n). Ignora que el paréntesis cierra la base. Es un error de lectura de la notación, no de la regla.$c$, $c$(2^3)^2 = 2^9$c$, $c$NUM$c$, $c$NUM-POT-POT$c$, $c$hipotesis$c$),
  ($c$POT-CERO-BASE$c$, $c$El exponente cero devuelve la base$c$, $c$Cree que a^0 = a. Trata el exponente cero como si no hiciera nada, en vez de reconocer que define un valor distinto.$c$, $c$7^0 = 7$c$, $c$NUM$c$, $c$NUM-POT-CERO$c$, $c$hipotesis$c$),
  ($c$POT-CERO-NULO$c$, $c$El exponente cero anula$c$, $c$Cree que a^0 = 0. Traslada la idea de "multiplicar por cero da cero" al exponente. Es el error más frecuente del nodo y aparece cada vez que un cociente de exponentes iguales da 1.$c$, $c$7^0 = 0$c$, $c$NUM$c$, $c$NUM-POT-CERO$c$, $c$hipotesis$c$),
  ($c$POT-CERO-SIGNO$c$, $c$Aplica el exponente cero al signo$c$, $c$Resuelve -3^0 como si fuera (-3)^0 y responde 1. No distingue que sin paréntesis el exponente afecta solo al 3. Cruza con POT-SIG y DEMRE lo usa seguido.$c$, $c$-3^0 = 1$c$, $c$NUM$c$, $c$NUM-POT-CERO$c$, $c$hipotesis$c$),
  ($c$POT-UNO-UNO$c$, $c$Confunde exponente uno con resultado uno$c$, $c$Cree que a^1 = 1. Mezcla la regla del exponente cero con la del uno. Suele aparecer justo después de aprender que a^0 = 1.$c$, $c$8^1 = 1$c$, $c$NUM$c$, $c$NUM-POT-CERO$c$, $c$hipotesis$c$),
  ($c$POT-DIST-NUM$c$, $c$Eleva solo el numerador$c$, $c$Resuelve (a/b)^n como a^n/b. Es POT-DIST-UNO en el cociente, pero se registra aparte porque el estudiante que lo tiene suele resolver bien el producto: la fracción esconde el segundo factor.$c$, $c$(2/3)^2 = 4/3$c$, $c$NUM$c$, $c$NUM-POT-DIST$c$, $c$hipotesis$c$),
  ($c$POT-DIST-SUMA$c$, $c$Reparte el exponente sobre una suma$c$, $c$Aplica (a+b)^n = a^n + b^n. Extiende a la suma una regla que solo vale para producto y cociente. Es el error más caro del nodo porque sobrevive hasta álgebra y reaparece en ALG-NOT-BIN2.$c$, $c$(x + y)^2 = x^2 + y^2$c$, $c$NUM$c$, $c$NUM-POT-DIST$c$, $c$hipotesis$c$),
  ($c$POT-DIST-UNO$c$, $c$Aplica el exponente a un solo factor$c$, $c$Resuelve (a·b)^n elevando solo uno de los factores. Casi siempre deja el número sin elevar y eleva la letra: (3x)^2 = 3x^2. El paréntesis se lee como si no estuviera.$c$, $c$(3x)^2 = 3x^2$c$, $c$NUM$c$, $c$NUM-POT-DIST$c$, $c$hipotesis$c$),
  ($c$POT-FRA-CREC$c$, $c$Cree que elevar siempre agranda$c$, $c$Generaliza desde los enteros: como 2^3 > 2, supone que (1/2)^3 > 1/2. Con base entre 0 y 1 elevar achica, y eso rompe la intuición. Es una creencia sobre el tamaño del resultado, no un error de procedimiento: se detecta con ítems de comparación, no de cálculo.$c$, $c$(1/2)^4 > 1/2$c$, $c$NUM$c$, $c$NUM-POT-FRA$c$, $c$hipotesis$c$),
  ($c$POT-FRA-DEN$c$, $c$Eleva solo el denominador$c$, $c$Resuelve (a/b)^n como a/b^n. Error espejo de POT-DIST-NUM. Se esconde cuando el numerador es 1, porque ahí elevar o no elevar da lo mismo: (1/2)^3 = 1/8 por el camino correcto y por el equivocado.$c$, $c$(2/3)^2 = 2/9$c$, $c$NUM$c$, $c$NUM-POT-FRA$c$, $c$hipotesis$c$),
  ($c$POT-FRA-INV$c$, $c$Invierte la fracción al elevarla$c$, $c$Da vuelta numerador y denominador antes de elevar. Confunde la regla de la potencia con la del exponente negativo, que todavía no ve. Emparentado con POT-CERO-INV, que hace lo mismo con exponente cero.$c$, $c$(2/3)^2 = 9/4$c$, $c$NUM$c$, $c$NUM-POT-FRA$c$, $c$hipotesis$c$),
  ($c$POT-CERO-INV$c$, $c$Interpreta el exponente cero como inverso$c$, $c$Responde el recíproco de la base ante un exponente cero, confundiendo la regla con la del exponente negativo. Su nodo de origen es NUM-POT-NEG, que el estudiante todavía no vio.$c$, $c$(2/5)^0 = 5/2$c$, $c$NUM$c$, $c$NUM-POT-NEG$c$, $c$hipotesis$c$),
  ($c$POT-NEG-INVMULT$c$, $c$Invierte la base y multiplica por el exponente$c$, $c$Reconoce que el exponente negativo invierte, pero después opera la base con el exponente en vez de elevarla. Mezcla la regla nueva con POT-CONC-MULT.$c$, $c$2^-3 = 1/6$c$, $c$NUM$c$, $c$NUM-POT-NEG$c$, $c$hipotesis$c$),
  ($c$POT-NEG-MANTIENE$c$, $c$Invierte la base y conserva el exponente negativo$c$, $c$Da vuelta la fracción pero no cambia el signo del exponente, y queda con una expresión equivalente a la original. El paso está bien aprendido a medias: falta que invertir y cambiar el signo son la misma operación.$c$, $c$(2/5)^-3 = (5/2)^-3$c$, $c$NUM$c$, $c$NUM-POT-NEG$c$, $c$hipotesis$c$),
  ($c$POT-NEG-RAIZ$c$, $c$Lee el exponente negativo como raíz$c$, $c$Confunde el exponente negativo con el racional. Aparece cuando las dos reglas se enseñan seguidas y queda el recuerdo de que "el exponente raro no es una multiplicación".$c$, $c$8^-3 = raíz cúbica de 8$c$, $c$NUM$c$, $c$NUM-POT-NEG$c$, $c$hipotesis$c$),
  ($c$POT-NEG-SIGNO$c$, $c$El exponente negativo hace negativo el resultado$c$, $c$Traslada el signo del exponente al resultado: a^(-n) = -(a^n). Es el error central del nodo y el que más lejos llega: sobrevive hasta notación científica y función exponencial.$c$, $c$2^-3 = -8$c$, $c$NUM$c$, $c$NUM-POT-NEG$c$, $c$hipotesis$c$),
  ($c$POT-CIENT-DIR$c$, $c$Invierte la dirección del exponente$c$, $c$Asocia exponente negativo con número grande y positivo con número chico, o mueve la coma para el lado contrario. Suele venir arrastrado de POT-NEG-SIGNO.$c$, $c$6,5 · 10^-5 = 650 000$c$, $c$NUM$c$, $c$NUM-POT-CIENT$c$, $c$hipotesis$c$),
  ($c$POT-CIENT-LUGAR$c$, $c$Cuenta ceros en vez de posiciones$c$, $c$Determina el exponente contando los ceros del número en vez de los lugares que se mueve la coma. Falla por uno cada vez que hay dígitos distintos de cero después del primero.$c$, $c$45 000 = 4,5 · 10^3$c$, $c$NUM$c$, $c$NUM-POT-CIENT$c$, $c$hipotesis$c$),
  ($c$POT-CIENT-MANT$c$, $c$Acepta mantisa fuera de 1 a 10$c$, $c$Escribe el número como producto por una potencia de diez sin exigir que la mantisa tenga un solo dígito antes de la coma. El valor es correcto pero la forma no es notación científica.$c$, $c$45 000 = 45 · 10^3$c$, $c$NUM$c$, $c$NUM-POT-CIENT$c$, $c$hipotesis$c$),
  ($c$POT-RAC-ENTERO$c$, $c$Ignora el denominador del exponente$c$, $c$Se queda solo con el numerador y trata el exponente como entero. La fracción se lee como decoración.$c$, $c$8^(2/3) = 64$c$, $c$NUM$c$, $c$NUM-POT-RAC$c$, $c$hipotesis$c$),
  ($c$POT-RAC-INV$c$, $c$Confunde el exponente fraccionario con el negativo$c$, $c$Responde el recíproco ante un exponente fraccionario. Error espejo de POT-NEG-RAIZ: las dos reglas se mezclan en las dos direcciones.$c$, $c$8^(1/3) = 1/8$c$, $c$NUM$c$, $c$NUM-POT-RAC$c$, $c$hipotesis$c$),
  ($c$POT-RAC-INVERSO$c$, $c$Intercambia índice y exponente$c$, $c$Lee a^(m/n) como la raíz m-ésima de a^n en vez de la raíz n-ésima de a^m. El numerador y el denominador quedan cambiados de rol.$c$, $c$8^(2/3) = raíz cuadrada de 8^3$c$, $c$NUM$c$, $c$NUM-POT-RAC$c$, $c$hipotesis$c$),
  ($c$POT-CONC-ORDEN$c$, $c$Opera antes de resolver la potencia$c$, $c$En expresiones mixtas resuelve la multiplicación o la suma antes que la potencia. No es un error de potencias sino de prioridad, y su nodo de origen es NUM-ENT-PRIOR. Se detecta acá porque acá es donde aparece.$c$, $c$3 · 2^3 = 6^3 = 216$c$, $c$NUM$c$, $c$NUM-ENT-PRIOR$c$, $c$hipotesis$c$)
) as v(code, name, description, example, area_code, node_code, origin)
left join areas a on a.code = v.area_code
join nodes n      on n.code = v.node_code
on conflict (code) do update
  set name        = excluded.name,
      description = excluded.description,
      example     = excluded.example,
      node_id     = excluded.node_id,
      origin      = excluded.origin;

-- Verificación. Si algo no cuadra, revienta y no commitea. ----------
do $verif$
declare c integer;
begin
  select count(*) into c from misconceptions where code in ($c$POT-CONC-FACTOR$c$, $c$POT-CONC-INV$c$, $c$POT-CONC-MULT$c$, $c$POT-CONC-SUMA$c$, $c$POT-SIG-EXP$c$, $c$POT-SIG-NEG$c$, $c$POT-SIG-PAREN$c$, $c$POT-SIG-POS$c$, $c$POT-BASE-DIST$c$, $c$POT-BASE-OPERA$c$, $c$POT-COC-DIV$c$, $c$POT-COC-ORDEN$c$, $c$POT-COC-SUMA$c$, $c$POT-EXP-UNO$c$, $c$POT-PROD-MULT$c$, $c$POT-PROD-RESTA$c$, $c$POT-SUMA-PROD$c$, $c$POT-POT-BASE$c$, $c$POT-POT-SUMA$c$, $c$POT-POT-TORRE$c$, $c$POT-CERO-BASE$c$, $c$POT-CERO-NULO$c$, $c$POT-CERO-SIGNO$c$, $c$POT-UNO-UNO$c$, $c$POT-DIST-NUM$c$, $c$POT-DIST-SUMA$c$, $c$POT-DIST-UNO$c$, $c$POT-FRA-CREC$c$, $c$POT-FRA-DEN$c$, $c$POT-FRA-INV$c$, $c$POT-CERO-INV$c$, $c$POT-NEG-INVMULT$c$, $c$POT-NEG-MANTIENE$c$, $c$POT-NEG-RAIZ$c$, $c$POT-NEG-SIGNO$c$, $c$POT-CIENT-DIR$c$, $c$POT-CIENT-LUGAR$c$, $c$POT-CIENT-MANT$c$, $c$POT-RAC-ENTERO$c$, $c$POT-RAC-INV$c$, $c$POT-RAC-INVERSO$c$, $c$POT-CONC-ORDEN$c$);
  if c <> 42 then
    raise exception 'catalogo NUM-POT: se esperaban 42, hay %', c; end if;

  select count(*) into c from misconceptions
   where code in ($c$POT-CONC-FACTOR$c$, $c$POT-CONC-INV$c$, $c$POT-CONC-MULT$c$, $c$POT-CONC-SUMA$c$, $c$POT-SIG-EXP$c$, $c$POT-SIG-NEG$c$, $c$POT-SIG-PAREN$c$, $c$POT-SIG-POS$c$, $c$POT-BASE-DIST$c$, $c$POT-BASE-OPERA$c$, $c$POT-COC-DIV$c$, $c$POT-COC-ORDEN$c$, $c$POT-COC-SUMA$c$, $c$POT-EXP-UNO$c$, $c$POT-PROD-MULT$c$, $c$POT-PROD-RESTA$c$, $c$POT-SUMA-PROD$c$, $c$POT-POT-BASE$c$, $c$POT-POT-SUMA$c$, $c$POT-POT-TORRE$c$, $c$POT-CERO-BASE$c$, $c$POT-CERO-NULO$c$, $c$POT-CERO-SIGNO$c$, $c$POT-UNO-UNO$c$, $c$POT-DIST-NUM$c$, $c$POT-DIST-SUMA$c$, $c$POT-DIST-UNO$c$, $c$POT-FRA-CREC$c$, $c$POT-FRA-DEN$c$, $c$POT-FRA-INV$c$, $c$POT-CERO-INV$c$, $c$POT-NEG-INVMULT$c$, $c$POT-NEG-MANTIENE$c$, $c$POT-NEG-RAIZ$c$, $c$POT-NEG-SIGNO$c$, $c$POT-CIENT-DIR$c$, $c$POT-CIENT-LUGAR$c$, $c$POT-CIENT-MANT$c$, $c$POT-RAC-ENTERO$c$, $c$POT-RAC-INV$c$, $c$POT-RAC-INVERSO$c$, $c$POT-CONC-ORDEN$c$) and node_id is null;
  if c <> 0 then
    raise exception '% errores sin nodo donde se ensenan', c; end if;

  select count(*) into c from misconceptions
   where code in ($c$POT-CONC-FACTOR$c$, $c$POT-CONC-INV$c$, $c$POT-CONC-MULT$c$, $c$POT-CONC-SUMA$c$, $c$POT-SIG-EXP$c$, $c$POT-SIG-NEG$c$, $c$POT-SIG-PAREN$c$, $c$POT-SIG-POS$c$, $c$POT-BASE-DIST$c$, $c$POT-BASE-OPERA$c$, $c$POT-COC-DIV$c$, $c$POT-COC-ORDEN$c$, $c$POT-COC-SUMA$c$, $c$POT-EXP-UNO$c$, $c$POT-PROD-MULT$c$, $c$POT-PROD-RESTA$c$, $c$POT-SUMA-PROD$c$, $c$POT-POT-BASE$c$, $c$POT-POT-SUMA$c$, $c$POT-POT-TORRE$c$, $c$POT-CERO-BASE$c$, $c$POT-CERO-NULO$c$, $c$POT-CERO-SIGNO$c$, $c$POT-UNO-UNO$c$, $c$POT-DIST-NUM$c$, $c$POT-DIST-SUMA$c$, $c$POT-DIST-UNO$c$, $c$POT-FRA-CREC$c$, $c$POT-FRA-DEN$c$, $c$POT-FRA-INV$c$, $c$POT-CERO-INV$c$, $c$POT-NEG-INVMULT$c$, $c$POT-NEG-MANTIENE$c$, $c$POT-NEG-RAIZ$c$, $c$POT-NEG-SIGNO$c$, $c$POT-CIENT-DIR$c$, $c$POT-CIENT-LUGAR$c$, $c$POT-CIENT-MANT$c$, $c$POT-RAC-ENTERO$c$, $c$POT-RAC-INV$c$, $c$POT-RAC-INVERSO$c$, $c$POT-CONC-ORDEN$c$) and (example is null or example = '');
  if c <> 0 then
    raise exception '% errores sin example', c; end if;
end
$verif$;

-- 42 misconceptions en NUM-POT (42 hipotesis).
